import{_ as d,o,c as e,a2 as a}from"./chunks/framework.BM5YPQmL.js";const E=JSON.parse('{"title":"OCBL：双固件引导与 A/B 槽判定","description":"","frontmatter":{},"headers":[],"relativePath":"zh/components/ocbl/ocbl-ab.md","filePath":"zh/components/ocbl/ocbl-ab.md"}'),r={name:"zh/components/ocbl/ocbl-ab.md"};function c(l,t,h,s,i,n){return o(),e("div",null,[...t[0]||(t[0]=[a('<h1 id="ocbl-双固件引导与-a-b-槽判定" tabindex="-1">OCBL：双固件引导与 A/B 槽判定 <a class="header-anchor" href="#ocbl-双固件引导与-a-b-槽判定" aria-label="Permalink to &quot;OCBL：双固件引导与 A/B 槽判定&quot;">​</a></h1><p>OCBL 如何决定启动什么、恢复盘上的 A/B 槽如何判定、两个低内存状态 区各是什么含义。该契约由三个独立构建逐字节共享——OCBL（<code>ocbl/</code>）、 OCOS 内核（<code>src/L0/</code>）、OCIRE 恢复内核（<code>ocire/</code>）——定义在 <code>include/ocbl_state.h</code>。</p><h2 id="a-b-恢复盘-两个独立物理分区" tabindex="-1">A/B 恢复盘：两个独立物理分区 <a class="header-anchor" href="#a-b-恢复盘-两个独立物理分区" aria-label="Permalink to &quot;A/B 恢复盘：两个独立物理分区&quot;">​</a></h2><p>WP-07 恢复盘以<strong>两个独立物理分区</strong>承载 OCIRE：</p><table tabindex="0"><thead><tr><th>槽</th><th>分区</th><th>起始 LBA</th><th>容量</th><th>文件系统</th></tr></thead><tbody><tr><td>OCIRE-A</td><td>p1</td><td>2048</td><td>64 MiB</td><td>真 FAT32，支持 LFN 读取</td></tr><tr><td>OCIRE-B</td><td>p2</td><td>133120</td><td>64 MiB</td><td>真 FAT32，支持 LFN 读取</td></tr></tbody></table><p>这是真正的双分区布局——<strong>不是</strong>一个分区里放两个镜像文件。较老的 FAT12 0xEE 影子卷介质仍可挂载（兼容性）；现行介质上影子布局已 退役。</p><p>槽位选择块是 <strong>LBA 1024 处的 A/B 标志扇区</strong>，位于 OCBL 镜像与首个 分区之间——一个 24 字节的 <code>OCIREAB1</code> 结构，OCBL 与 OCIRE 逐字节 共享其布局：</p><table tabindex="0"><thead><tr><th>字段</th><th>含义</th></tr></thead><tbody><tr><td><code>magic[8]</code></td><td><code>&quot;OCIREAB1&quot;</code></td></tr><tr><td><code>active_slot</code></td><td>1 = A，2 = B（最后一次确认良好的槽）</td></tr><tr><td><code>try_slot</code></td><td>0 = 无；否则正在尝试的候选槽</td></tr><tr><td><code>attempts</code></td><td>对 <code>try_slot</code> 已作出的启动尝试次数</td></tr><tr><td><code>flags</code></td><td>位 0 = 脏</td></tr><tr><td><code>boot_count</code></td><td>OCIRE 成功启动次数</td></tr></tbody></table><h2 id="槽位判定流程" tabindex="-1">槽位判定流程 <a class="header-anchor" href="#槽位判定流程" aria-label="Permalink to &quot;槽位判定流程&quot;">​</a></h2><ol><li>OCBL 读标志扇区并选槽：有 <code>try_slot</code> 则用之，否则用 <code>active_slot</code>。</li><li>加载候选<strong>之前</strong>先递增其 <code>attempts</code>。</li><li>候选无法加载时，OCBL 回退到另一个槽。</li><li>正常运行的槽由 <strong>OCIRE 确认</strong>（晋升）：恢复内核在一次良好启动 后更新标志扇区，<code>active_slot</code> 由此为真。</li></ol><p>OCOS 的 A/B 回滚使用与被它取代的 GRUB 配置相同形态的协议（磁盘 首个系统卷上的 <code>next_B</code> / <code>ok_B</code> / <code>bootfail_B</code>）——接管菜单的 Rollback 键翻转的正是这些标志。</p><h2 id="两个状态区" tabindex="-1">两个状态区 <a class="header-anchor" href="#两个状态区" aria-label="Permalink to &quot;两个状态区&quot;">​</a></h2><p>两块固定低内存实现启动状态监视。两处都经参考平台实测在热复位中 存活（复位的擦除停在 EBDA，0x9FC00）；<strong>冷启动或断电会清除它们</strong>， 因此每个消费者在校验魔数与反码校验和之前不信任任何记录——没有 记录只意味着一次正常启动，绝不误判为失败。</p><table tabindex="0"><thead><tr><th>区域</th><th>地址</th><th>大小</th><th>写入者</th><th>读取者</th><th>含义</th></tr></thead><tbody><tr><td>STATE</td><td><code>0x98000</code></td><td>4 KiB</td><td>内核<strong>盲写</strong>（从不回读）；OCBL 在移交时重新初始化</td><td>OCBL、OCIRE</td><td>内核此刻在做什么：阶段、心跳、进度时钟</td></tr><tr><td>RESERVED</td><td><code>0x9B000</code></td><td>4 KiB</td><td>OCBL（判定或用户请求）</td><td>OCIRE，重启后</td><td>事后启动记录</td></tr></tbody></table><p>两页在每个用户地址空间中都是仅监督者可见——L1 应用够不到——且 都在 multiboot2 内存映射中被划为 E820 保留，任何载荷都不会分配 它们。</p><h3 id="启动阶段-state-区的-stage-字段" tabindex="-1">启动阶段（STATE 区的 <code>stage</code> 字段） <a class="header-anchor" href="#启动阶段-state-区的-stage-字段" aria-label="Permalink to &quot;启动阶段（STATE 区的 `stage` 字段）&quot;">​</a></h3><p>数值顺序即启动顺序；内核只前进：</p><table tabindex="0"><thead><tr><th>#</th><th>阶段</th><th>含义</th></tr></thead><tbody><tr><td>0</td><td>BOOT</td><td>kmain 之前的移交</td></tr><tr><td>1</td><td>KMAIN_ENTERED</td><td>kmain() 已进入</td></tr><tr><td>2</td><td>SCHED_READY</td><td>调度器 + 核心机制</td></tr><tr><td>3</td><td>DRIVERS_READY</td><td>驱动初始化完成</td></tr><tr><td>4</td><td>SERVICES_READY</td><td>根服务就绪</td></tr><tr><td>5</td><td>L1_LAUNCHED</td><td>默认 L1 应用已启动</td></tr><tr><td>6</td><td>L1_READY</td><td>ush 已服务（首次系统调用）</td></tr><tr><td>255</td><td>RUNTIME</td><td>标记：运行中挂死</td></tr></tbody></table><h2 id="失败计数与清零条件" tabindex="-1">失败计数与清零条件 <a class="header-anchor" href="#失败计数与清零条件" aria-label="Permalink to &quot;失败计数与清零条件&quot;">​</a></h2><ul><li><strong>单次</strong>被判定的启动失败只递增记录的 <code>boot_fails</code> 计数并 <strong>重试 OCOS</strong>。</li><li>计数达到 <strong>2</strong>（<code>OCST_BOOT_FAILS_ROUTE</code>）时，OCBL 自动把机器 路由进 OCIRE——接管。</li><li>内核在<strong>确认良好启动后</strong>（到达 L1_READY）清零计数器，所以 &quot;连续&quot;是诚实的：一次坏启动后跟一次好启动，计数器归零。</li><li>计数器使用记录中原先的保留字节——记录布局未变，旧读取者继续 工作。</li></ul><h2 id="看门狗接力-谁在给谁计时" tabindex="-1">看门狗接力（谁在给谁计时） <a class="header-anchor" href="#看门狗接力-谁在给谁计时" aria-label="Permalink to &quot;看门狗接力（谁在给谁计时）&quot;">​</a></h2><p>multiboot2 移交之后 OCBL 已不再执行，因此各阶段超时由 <strong>i6300ESB 硬件看门狗</strong>强制：OCBL 在移交前布防引导预算，内核在 每次阶段推进时重布阶段预算，并在运行时以 1 秒节拍喂狗。</p><table tabindex="0"><thead><tr><th>阶段</th><th>预算</th></tr></thead><tbody><tr><td>启动起点 -&gt; KMAIN_ENTERED</td><td>30 秒（OCBL 移交前布防）</td></tr><tr><td>各中间阶段</td><td>10 秒</td></tr><tr><td>L1_LAUNCHED -&gt; L1_READY</td><td>30 秒</td></tr><tr><td>运行时（L1_READY 之后）</td><td>15 秒心跳（1 秒节拍喂狗）</td></tr></tbody></table><p>内核挂死即停喂狗，硬件复位机器，而复位后再次运行的 OCBL 读取 状态区、依据阶段与实测静默时长判定停滞（<strong>8 秒</strong>的阈值把手动 热复位——实测静默不足 ~4 秒——与真实看门狗捕获的挂死——至少 达到运行时预算——分开），把 BOOT_FAILED 写入保留区，在屏幕上 显示失败通告 4 秒，然后发 8042 复位脉冲。</p><h2 id="sleep-armed-唤醒失败检测器" tabindex="-1">SLEEP_ARMED（唤醒失败检测器） <a class="header-anchor" href="#sleep-armed-唤醒失败检测器" aria-label="Permalink to &quot;SLEEP_ARMED（唤醒失败检测器）&quot;">​</a></h2><p>内核在写入 SLP_EN（进入 S3/S0ix）之前立即置位 <code>SLEEP_ARMED</code> 标志，并在恢复路径上清除它。重启后仍发现该标志置位，意味着唤醒 向量崩溃或机器在睡眠中死亡：OCBL 记录 WAKE_FAILED 并路由 OCIRE， 后者给出唤醒失败接管菜单。</p><p>下一篇：<a href="./ocbl-troubleshooting.html">故障排查与状态码</a>。</p>',27)])])}const _=d(r,[["render",c]]);export{E as __pageData,_ as default};
